# define PI 3.14159265359
vec2 hash(vec2 x){
    vec2 p  = vec2(
                dot(x, vec2(3451.4327, 2744.749)),
                dot(x, vec2(2453.4327, 3218.127)));
    return fract( sin(p)*3745.4);
}

