float make_ellipse(vec2 U, vec2 ab, float amp, float a) {

    vec2 A = vec2( cos(a), sin(a) ), A2 = A*A,
        B2 = ab*ab,
         C = A*U;

    float a2b2 = B2.x*B2.y,
             c = 2.* C.x*C.y* (B2.y-B2.x) / a2b2;

    vec2 Q = mat2(A2.y,A2.x, A2) * B2  * U*U / a2b2;

    return smoothstep( 10./iResolution.y, 0., abs( Q.x+ Q.y + c - amp ) );
}


mat2 rotation_matrix(float angle){
    return mat2(cos(angle), sin(angle), -sin(angle), cos(angle));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = ( 2.*fragCoord.xy - iResolution.xy ) / iResolution.y;
    uv /= 1.5;

    // N ellipse
    float N = 11.;

    // Time varying pixel color
    vec3 col;
    vec3 tmp_color = vec3(1., 1., 1.);
    vec2 ab = vec2(.3+.2*cos(iTime), .2);


    for (int i=0; i<int(N); i++){
        vec2 st = uv;
        float angle = (2.*PI*float(i)/N)+iTime+.1;
        mat2 rot = rotation_matrix(angle);

        vec2 tmp_ab = mix(ab, vec2(.2, .2)+0.05*hash(vec2(float(i), angle)), smoothstep(0.4,0.6, cos(iTime*.1)));

        st += rot*mix(vec2(.1, .1), vec2(0., 0.)+0.05*hash(vec2(angle, float(i))), smoothstep(0.3,0.7, abs(cos(iTime*.1))));
        col += vec3(1.,0.,0.)*make_ellipse(st, tmp_ab, .3+.3*cos(iTime*2.), angle);
    }

        for (int i=0; i<int(N); i++){
        vec2 st = uv;
        float angle = (2.*PI*float(i)/N)+iTime;
        mat2 rot = rotation_matrix(angle);

        vec2 tmp_ab = mix(ab, vec2(.2, .2)+0.05*hash(vec2(float(i), angle)), smoothstep(0.4,0.6, cos(iTime*.1)));

        st += rot*mix(vec2(.1, .1), vec2(0., 0.)+0.05*hash(vec2(angle, float(i))), smoothstep(0.3,0.7, abs(cos(iTime*.1))));
        col += vec3(0.,1.,0.)*make_ellipse(st, tmp_ab, .3+.3*cos(iTime*2.), angle);
    }

        for (int i=0; i<int(N); i++){
        vec2 st = uv;
        float angle = (2.*PI*float(i)/N)+iTime-.1;
        mat2 rot = rotation_matrix(angle);

        vec2 tmp_ab = mix(ab, vec2(.2, .2)+0.05*hash(vec2(float(i), angle)), smoothstep(0.4,0.6, cos(iTime*.1)));

        st += rot*mix(vec2(.1, .1), vec2(0., 0.)+0.05*hash(vec2(angle, float(i))), smoothstep(0.3,0.7, abs(cos(iTime*.1))));
        col += vec3(0.,0.,1.)*make_ellipse(st, tmp_ab, .3+.3*cos(iTime*2.), angle);
    }
    // Output to screen

    fragColor = vec4(col,1.0);
}
